/* GSHHS intermediate-resolution Balkan coast; 160 x 116 hex-centre tiles, 25 subsamples per tile.
 * Geographic bounds W15.0, E31.8, N47.3, S34.8. 2-bit classifications: 0 water, 1 mixed coast, 2 land.
 * RLE (count,byte) of packed four 2-bit tiles per byte, Base64 encoded. No network assets. */
(function(root){'use strict';const compressed='';
  const raw=typeof atob==='function'?atob(compressed):Buffer.from(compressed,'base64').toString('latin1');
  let bytes='';for(let i=0;i<raw.length;i+=2)bytes+=String.fromCharCode(raw.charCodeAt(i+1)).repeat(raw.charCodeAt(i));
  if(bytes.length!==160*116/4)throw Error('Balkan shoreline RLE corrupt');
  root.CF_EU_BALKANS_COAST=bytes;
  if(typeof module!=='undefined')module.exports=bytes;
})(typeof window!=='undefined'?window:globalThis);
